<template><form class="task-form" @submit.prevent="enviar"><section><div class="form-section-title"><span>01</span><div><h2>Informações principais</h2><p>Identifique o compromisso para os alunos.</p></div></div><ion-input v-model="form.titulo" label="Título" label-placement="stacked" fill="outline" placeholder="Ex.: Lista de exercícios — Funções" :maxlength="80" required/><ion-textarea v-model="form.descricao" label="Descrição" label-placement="stacked" fill="outline" :auto-grow="true" :maxlength="500" placeholder="Oriente os alunos sobre o que deve ser feito" required/></section><section><div class="form-section-title"><span>02</span><div><h2>Classificação</h2><p>Organize por matéria, turma e tipo.</p></div></div><div class="form-grid"><ion-select v-model="form.materia" label="Matéria" label-placement="stacked" fill="outline" placeholder="Selecione" required><ion-select-option v-for="item in MATERIAS" :key="item" :value="item">{{item}}</ion-select-option></ion-select><ion-select v-model="form.turma" label="Turma" label-placement="stacked" fill="outline" placeholder="Selecione" required><ion-select-option v-for="item in turmasPermitidas" :key="item" :value="item">{{item}}</ion-select-option></ion-select><ion-select v-model="form.tipo" label="Tipo" label-placement="stacked" fill="outline"><ion-select-option v-for="item in TIPOS_ATIVIDADE" :key="item" :value="item">{{item}}</ion-select-option></ion-select><ion-select v-model="form.prioridade" label="Prioridade" label-placement="stacked" fill="outline"><ion-select-option v-for="item in PRIORIDADES" :key="item" :value="item">{{item}}</ion-select-option></ion-select></div></section><section><div class="form-section-title"><span>03</span><div><h2>Prazo de entrega</h2><p>Defina a data e um horário opcional.</p></div></div><div class="deadline-grid"><ion-input v-model="form.data" type="date" label="Data" label-placement="stacked" fill="outline" :min="hoje" required/><ion-input v-model="form.horario" type="time" label="Horário (opcional)" label-placement="stacked" fill="outline"/></div></section><p v-if="erro" class="error" role="alert">{{erro}}</p><ion-button type="submit" expand="block" size="large" :disabled="salvando"><ion-spinner v-if="salvando" name="crescent"/><span v-else>{{rotulo}}</span></ion-button></form></template>
<script setup lang="ts">
import { computed,reactive,watch } from 'vue';import { IonButton,IonInput,IonSelect,IonSelectOption,IonSpinner,IonTextarea } from '@ionic/vue';import { MATERIAS,PRIORIDADES,TIPOS_ATIVIDADE,type Prioridade,type TipoAtividade } from '../types';import { getUsuarioAtual } from '../services/auth.service';import { formatarISO } from '../utils/datas';
export interface FormAtividade{titulo:string;descricao:string;materia:string;turma:string;tipo:TipoAtividade;prioridade:Prioridade;data:string;horario:string}
const props=withDefaults(defineProps<{inicial?:Partial<FormAtividade>;salvando?:boolean;erro?:string;rotulo?:string}>(),{rotulo:'Publicar atividade'});const emit=defineEmits<{salvar:[dados:FormAtividade]}>();
const usuario=getUsuarioAtual();const turmasPermitidas=computed(()=>usuario.value?.turmas||[]);const form=reactive<FormAtividade>({titulo:'',descricao:'',materia:'',turma:'',tipo:'Atividade',prioridade:'Média',data:formatarISO(new Date(Date.now()+86400000)),horario:'18:00'});const hoje=formatarISO(new Date());
watch(()=>props.inicial,(valor)=>{if(valor)Object.assign(form,valor)},{immediate:true,deep:true});
function enviar(){if(!turmasPermitidas.value.includes(form.turma)||!form.titulo.trim()||!form.descricao.trim()){return}emit('salvar',{...form,titulo:form.titulo.trim(),descricao:form.descricao.trim()})}
</script>
